def apply_replacements(text: str, mapping: dict[str, str]) -> str:
    for source, target in sorted(mapping.items(), key=lambda item: len(item[0]), reverse=True):
        text = text.replace(source, target)
    return text.replace("âœ“", "✓").replace("â€”", "—")


def main() -> None:
    updated = []
    for language, mapping in TRANSLATIONS.items():
        for relative in TARGET_FILES:
            path = DOC_ROOT / language / relative
            if not path.exists():
                continue
            original = path.read_text(encoding="utf-8")
            translated = apply_replacements(original, mapping)
            if translated != original:
                path.write_text(translated, encoding="utf-8")
                updated.append(path.relative_to(BASE_DIR).as_posix())
    print(f"Updated {len(updated)} files")
    for item in updated:
        print(f"- {item}")


if __name__ == "__main__":
    main()
